class Solution {
    public: int countSpecialIntegers(vector<int>& nums) {
        vector<vector<int>> pos(101);
        for(int i=0; i<(int)nums.size(); i++)pos[nums[i]].push_back(i);
        int ans=0;
        for(auto &p:pos)if(p.size()==3 && p[1]-p[0]==p[2]-p[1])ans++;
        return ans;
    }
}
